CREATE TABLE admin_roles(id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL UNIQUE, permissions LONGTEXT NOT NULL DEFAULT ('[]'), builtin BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
INSERT INTO admin_roles(id,name,permissions,builtin) VALUES(1,'超级管理员','["*"]',1),(2,'普通成员','["overview.view","workspace.use"]',1);
CREATE TABLE admin_accounts(user_id BIGINT PRIMARY KEY, enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), verified_at BIGINT,FOREIGN KEY (user_id) REFERENCES loom_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE admin_user_roles(user_id BIGINT NOT NULL,role_id BIGINT NOT NULL,PRIMARY KEY(user_id,role_id),FOREIGN KEY (user_id) REFERENCES loom_users(id),FOREIGN KEY (role_id) REFERENCES admin_roles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
INSERT INTO admin_accounts(user_id) SELECT id FROM loom_users;
INSERT INTO admin_user_roles(user_id,role_id) SELECT id,2 FROM loom_users;
CREATE TABLE admin_menus(id BIGINT PRIMARY KEY AUTO_INCREMENT,label VARCHAR(255) NOT NULL,path VARCHAR(255) NOT NULL,permission VARCHAR(255) NOT NULL,parent_id BIGINT,sort_order BIGINT NOT NULL DEFAULT 0,enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),FOREIGN KEY (parent_id) REFERENCES admin_menus(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
INSERT INTO admin_menus(id,label,path,permission,sort_order) VALUES(1,'总览','/admin#overview','overview.view',10),(2,'项目与任务','/admin#workspace','workspace.use',20),(3,'用户管理','/admin#users','users.manage',30),(4,'角色权限','/admin#roles','roles.manage',40),(5,'菜单管理','/admin#menus','menus.manage',50),(6,'系统配置','/admin#settings','settings.manage',60),(7,'操作审计','/admin#audit','audit.view',70);
CREATE TABLE admin_settings(`key` VARCHAR(255) PRIMARY KEY,value LONGTEXT NOT NULL,updated_at BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP())) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
INSERT INTO admin_settings(`key`,value) VALUES('site_name','Loom 管理后台'),('site_description','统一工作台，专注业务管理'),('registration_enabled','true');
CREATE TABLE admin_audit(id BIGINT PRIMARY KEY AUTO_INCREMENT,actor_id BIGINT,action VARCHAR(255) NOT NULL,target VARCHAR(255) NOT NULL,detail LONGTEXT NOT NULL,created BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP())) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX admin_audit_created ON admin_audit(created,id);
CREATE TABLE admin_account_tokens(token VARCHAR(255) PRIMARY KEY,user_id BIGINT NOT NULL,purpose VARCHAR(255) NOT NULL,expires BIGINT NOT NULL,FOREIGN KEY (user_id) REFERENCES loom_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX admin_account_tokens_owner ON admin_account_tokens(user_id,purpose);
CREATE TABLE admin_mail(id BIGINT PRIMARY KEY AUTO_INCREMENT,recipient VARCHAR(255) NOT NULL,subject VARCHAR(255) NOT NULL,body LONGTEXT NOT NULL,state VARCHAR(255) NOT NULL DEFAULT 'pending',attempts BIGINT NOT NULL DEFAULT 0,available BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),lease_until BIGINT,created BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP())) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
